const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function setIcons(){document.querySelectorAll('[data-ic]').forEach(e=>{const t=e.querySelector('.ni,.si,.ki,span:empty')||e;(e.querySelector('.ni')||e.querySelector('.si')||e.querySelector('span')||e).innerHTML=ICONS[e.dataset.ic]||'';});$('#mk1').innerHTML=ICONS.reel;$('#mk2').innerHTML=ICONS.reel;}

/* ===== BLINDAGEM DE QUOTA DO LOCALSTORAGE =====
   O localStorage tem teto de ~5 MB. Com o catálogo gigante, ele encheu — e QUALQUER
   setItem passou a estourar QuotaExceeded. Como o pullLight faz saveStage() no meio,
   ele quebrava TODA vez → nunca voltava "Ao vivo" → offline eterno.
   Agora: se estourar, o app libera espaço sozinho (em etapas) e regrava. Nunca mais explode. */
(function(){
 if(!window.localStorage||window._lsGuard)return;window._lsGuard=1;
 var _raw=Storage.prototype.setItem;
 window._lsRawSet=function(k,v){return _raw.call(localStorage,k,v);};
 function liberar(passo){
  try{
   /* 1) catálogo de bobinas: agora mora no IndexedDB, não precisa ficar no localStorage */
    /* dados operacionais nunca são removidos automaticamente. O catálogo só é
       migrado para o IndexedDB depois que a gravação for confirmada. */
    if(passo===0)return false;
   /* 2) logs e caches descartáveis */
   if(passo===1){var t=false;['wmsx_fixlog','wmsx_printedEts','wmsx_etqDel'].forEach(function(k){if(localStorage.getItem(k)!=null){localStorage.removeItem(k);t=true;}});return t;}
   /* 3) histórico de movimentos: corta pros 3.000 mais recentes (o resto está na nuvem) */
   if(passo===2)return false; /* nunca remove movimentos nem atividades */
   /* 4) último recurso: corta movimentos pros 500 mais recentes */
   if(passo===3)return false; /* históricos operacionais são preservados */
  }catch(e){}
  return false;
 }
 Storage.prototype.setItem=function(k,v){
  try{return _raw.call(this,k,v);}
  catch(e){
   if(this!==window.localStorage)throw e;
   for(var p=0;p<4;p++){
    if(!liberar(p))continue;
    try{return _raw.call(this,k,v);}catch(e2){}
   }
   /* mesmo depois de limpar não coube: NÃO estoura (o dado está na nuvem/IndexedDB).
      Só registra pro diagnóstico — antes essa exceção derrubava o pullLight inteiro. */
    try{window._lsFull=Date.now();if(window._DIAG)window._DIAG.lsFull='cheio · chave '+k+' não coube';
      setTimeout(function(){try{if(typeof toast==='function')toast('⚠ Armazenamento local cheio. O dado não foi confirmado; mantenha esta tela aberta e verifique a conexão.',false);}catch(_e){}},0);
    }catch(_){}
    throw e;
  }
 };
})();

const DB=(()=>{const K={sp:'wmsx_sp',mv:'wmsx_mv',tr:'wmsx_tr',vl:'wmsx_vl',us:'wmsx_us',ac:'wmsx_ac',cf:'wmsx_cf'};
  const r=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d;}catch{return d;}};const w=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
  const seedSp=()=>SEED_SPACES.map(x=>({id:'70-'+x.s+'-'+x.p+'-'+x.l,w:'70',s:x.s,l:x.l,p:x.p,pr:(x.pr&&x.pr!=='0')?x.pr:'',q:x.q||0,u:'KG',o:!!x.o,src:x.src||'',upd:'',by:''}));
  function init(){if(!localStorage.getItem(K.sp))w(K.sp,seedSp());if(!localStorage.getItem(K.vl))w(K.vl,SEED_VALUES.map(c=>({codigo:c,valor:0,descricao:''})));if(!localStorage.getItem(K.us))w(K.us,[]);['mv','tr','ac'].forEach(k=>{if(!localStorage.getItem(K[k]))w(K[k],[]);});if(!localStorage.getItem(K.cf))w(K.cf,{warehouse:'70'});}
  return {init,seedSp,spaces:()=>r(K.sp,[]),saveSpaces:a=>w(K.sp,a),movs:()=>r(K.mv,[]),saveMovs:a=>w(K.mv,a),transf:()=>r(K.tr,[]),saveTransf:a=>w(K.tr,a),values:()=>r(K.vl,[]),saveValues:a=>w(K.vl,a),users:()=>r(K.us,[]),saveUsers:a=>w(K.us,a),act:()=>r(K.ac,[]),saveAct:a=>w(K.ac,a),cfg:()=>r(K.cf,{warehouse:'70'}),saveCfg:c=>w(K.cf,c),reseed:()=>w(K.sp,seedSp())};})();
