const ROLE_VIEWS={operador:['v-board','v-recv','v-floor','v-floor70','v-exped','v-mov','v-stock','v-recic','v-labels','v-inv','v-amrp'],recepcao:['v-nf','v-labels','v-recv','v-floor','v-floor70','v-inv']};
