function toast(m,ok=true){const t=$('#toast');$('#toastMsg').textContent=m;t.className='show '+(ok?'ok':'err');clearTimeout(t._t);t._t=setTimeout(()=>t.className='',2600);try{if(typeof scanFeedback==='function')scanFeedback(m,ok);}catch(e){}}
/* mostra o aviso GRANDE na tela da câmera quando ela está aberta (senão o toast fica atrás do vídeo e você não vê bipando) */
function scanFeedback(m,ok){try{
  var modal=document.getElementById('scan');if(!modal||!modal.classList.contains('show'))return;
  var fb=document.getElementById('scanFb');if(!fb)return;
  var bloqueio=(ok===false);
  fb.className='scanFb show '+(bloqueio?'err':'ok');
  fb.innerHTML='<div class="fbcard"><span class="fbico">'+(bloqueio?'⛔':'✓')+'</span><span>'+String(m).replace(/</g,'&lt;')+'</span></div>';
  try{if(navigator.vibrate)navigator.vibrate(bloqueio?[90,60,90]:35);}catch(e){}
  clearTimeout(fb._t);fb._t=setTimeout(function(){fb.className='scanFb';},bloqueio?2600:1300);
}catch(e){}}
/* ===== TRAVAMENTO AO CLICAR: RESOLVIDO AQUI =====
   persist() era chamado em TODA ação e serializava 6 listas de uma vez — incluindo o log de
   movimentos com até 20.000 registros. Cada clique fazia um JSON.stringify de vários MB na
   thread principal (50–300ms de congelamento) e ainda gravava tudo no localStorage.
   Agora:
   1) o envio pra nuvem continua IMEDIATO (nada de atraso no que importa);
   2) a gravação local pesada é agrupada (debounce de 200ms) — 10 cliques rápidos viram 1 gravação;
   3) tudo é descarregado na hora se a aba for fechada/escondida (não perde nada);
   4) o log de movimentos foi limitado a 5.000 (o histórico completo vive na nuvem). */
var _persistT=null,_persistPend=false;
function _persistFlush(){
 if(!_persistPend)return;
 _persistPend=false;clearTimeout(_persistT);_persistT=null;
 DB.saveSpaces(S);DB.saveMovs(MV);DB.saveTransf(TR);DB.saveValues(VL);DB.saveUsers(US);DB.saveAct(AC);
}
function persist(){
 try{if(typeof markLocalWrite==='function')markLocalWrite();}catch(e){}
 try{_persistSyncSpaces();}catch(e){}   /* nuvem: imediato */
 _persistPend=true;                      /* disco: agrupado */
 clearTimeout(_persistT);
 _persistT=setTimeout(_persistFlush,200);
}
window.persistFlush=_persistFlush;
/* rede de segurança: se fechar, recarregar ou trocar de aba, grava na hora */
window.addEventListener('beforeunload',_persistFlush);
window.addEventListener('pagehide',_persistFlush);
document.addEventListener('visibilitychange',function(){if(document.hidden)_persistFlush();});
/* ===== REDE DE SEGURANÇA: sincroniza pra nuvem TODA vaga cujo 'upd' mudou desde a última gravação.
   Assim, não importa qual dos vários fluxos alterou a vaga (entrada, saída, editar, produção,
   requisição, transferência...) — se ele chamou persist(), a vaga sobe. Corrige de vez o
   "fica ocupada e volta verde sozinho" e o "marco e não fica verde". ===== */
var _spSnap=Object.create(null);
function _persistSyncSpaces(){
  if(typeof supa==='undefined'||!supa||typeof syncSpace!=='function')return;
  if(!Array.isArray(S))return;
  var changed=[];
  for(var i=0;i<S.length;i++){var x=S[i];if(!x||!x.id)continue;var sig=(x.upd||'')+'|'+(x.o?1:0)+'|'+(x.pr||'')+'|'+(Number(x.q)||0);if(_spSnap[x.id]!==sig){_spSnap[x.id]=sig;changed.push(x);}}
  if(!changed.length)return;
  if(changed.length>60){try{if(typeof chunkUp==='function'&&typeof spRow==='function')chunkUp('espacos',changed.map(spRow));}catch(e){}}
  else{changed.forEach(function(x){try{syncSpace(x);}catch(e){}});}
}
/* na 1ª carga, tira uma foto do estado atual pra não re-subir o armazém inteiro à toa */
function _spSnapInit(){try{if(Array.isArray(S))S.forEach(function(x){if(x&&x.id)_spSnap[x.id]=(x.upd||'')+'|'+(x.o?1:0)+'|'+(x.pr||'')+'|'+(Number(x.q)||0);});}catch(e){}}
function logAct(a,d){AC.unshift({u:session?session.u:'-',action:a,details:d,at:nowISO()});DB.saveAct(AC);}
function rel(iso){if(!iso)return'—';const d=new Date(iso),s=(Date.now()-d)/1000;if(s<60)return'agora';if(s<3600)return Math.floor(s/60)+'min';if(s<86400)return Math.floor(s/3600)+'h';return d.toLocaleDateString('pt-BR');}
function findSpace(c){c=norm(c);return S.find(x=>x.w===cfg.warehouse&&code(x)===c);}
function valOf(c){const v=VL.find(x=>x.codigo===c);return v?Number(v.valor)||0:0;}
function occSpaces(){return S.filter(x=>x.w===cfg.warehouse&&x.o&&x.pr&&x.q>0);}

/* login */
function showLogin(){$('#login').style.display='flex';$('#logHint').textContent='';$('#logHint').style.color='';}
function logErr(msg){var h=$('#logHint');if(h){h.textContent=msg;h.style.color='#ff6b6b';h.style.fontWeight='700';}}
$('#logBtn').onclick=async()=>{try{
  const u=($('#logUser').value||'').trim(),p=$('#logPass').value||'';
  if(!u||!p){logErr('Preencha usuário e senha');return;}
  if(!Array.isArray(US))US=[];
  if(!US.length){const hash=await WMSSecurity.protect(p);US=[{u:u,p:hash,role:'admin',active:true}];DB.saveUsers(US);try{if(typeof supa!=='undefined'&&supa)await supa.from('usuarios').upsert({u:u,p:hash,role:'admin',active:true});}catch(_bootSync){}}
  const f=US.find(x=>x&&(x.u||'').toLowerCase()===u.toLowerCase()&&x.active!==false);
  const senhaOk=f?await WMSSecurity.verify(f.p,p):false;
  if(f&&senhaOk&&!WMSSecurity.isProtected(f.p)){f.p=await WMSSecurity.protect(p);DB.saveUsers(US);try{if(typeof supa!=='undefined'&&supa)await supa.from('usuarios').upsert({u:f.u,p:f.p,role:f.role,active:f.active!==false});}catch(_migrateSync){}}
  if(!senhaOk){logErr('Usuario ou senha incorretos');$('#logPass').value='';$('#logPass').focus();return;}
  if(!f){logErr('Usuário ou senha incorretos — tente de novo');$('#logPass').value='';$('#logPass').focus();return;}
  $('#logHint').textContent='';$('#logHint').style.color='';
  session={u:f.u,role:f.role};
  try{logAct('login',f.u);}catch(e){}
  $('#login').style.display='none';
  try{applyPerms();}catch(e){console.error('applyPerms',e);}
  try{refreshUser();}catch(e){console.error('refreshUser',e);}
  try{go('v-home');}catch(e){console.error('go home',e);try{go('v-recv');}catch(e2){}}
  $('#logPass').value='';
}catch(err){console.error('login',err);logErr('Erro ao entrar — atualize a página (Ctrl+Shift+R) e tente de novo');}};
$('#logUser').addEventListener('input',()=>{$('#logHint').textContent='';});
$('#logPass').addEventListener('input',()=>{$('#logHint').textContent='';});
$('#logPass').addEventListener('keydown',e=>{if(e.key==='Enter')$('#logBtn').click();});
$('#logoutBtn').onclick=()=>{logAct('logout',session.u);session=null;showLogin();};
function refreshUser(){$('#uName').textContent=session?session.u:'—';$('#uRole').textContent=session?session.role:'';}
function applyPerms(){const sup=isSuper();$$('.adminOnly').forEach(e=>e.style.display=sup?'':'none');const allow=allowedViews();$$('.nav').forEach(n=>{const v=n.dataset.view;if(allow){n.style.display=(allow.indexOf(v)>=0)?'':'none';}else if(!n.classList.contains('adminOnly')){n.style.display='';}});if(!sup&&cfg&&cfg.warehouse!=='70'){cfg.warehouse='70';try{DB.saveCfg(cfg);}catch(e){}}}

/* nav */
const TITLES={'v-home':'Visão Geral','v-board':'Mapa Operacional - 70','v-mov':'Movimentação','v-stock':'Gestão de Estoque','v-transf':'Transferências','v-labels':'Gestão de Etiquetas','v-abc':'Análise ABC','v-values':'Cadastro de Materiais','v-users':'Gestão de Usuários','v-act':'Log de Atividades'};
function go(id){if(id==='v-users'&&!isSuper())id='v-home';if(id==='v-mov'&&!isAdmin()){toast('Sem permissão para movimentar',false);return;}const allow=allowedViews();if(allow&&allow.indexOf(id)<0)id=allow[0]||'v-stock';
  /* Toda entrada nova em Documentos Fiscais exige escolher novamente PRE ou TÊXTIL.
     A regra fica aqui, no núcleo da navegação, para funcionar também quando o menu
     for reconstruído por login, troca de perfil ou permissões. */
  try{if(id==='v-nf'){var _nfAtual=document.querySelector('.view.active');if((!_nfAtual||_nfAtual.id!=='v-nf')&&typeof window.nfResetLocal==='function')window.nfResetLocal();}}catch(e){}
  /* ao entrar no Estoque, começa sempre limpo (fecha detalhe de card que ficou aberto) */
  try{if(id==='v-stock'){var _d=document.getElementById('stChaoDetail');if(_d)_d.innerHTML='';if(typeof _stMainToggle==='function')_stMainToggle(false);}}catch(e){}
  try{if(id==='v-labels'){var _lbx=document.getElementById('labelsBox');if(_lbx)_lbx.innerHTML='';var _plx=document.getElementById('printLabels');if(_plx)_plx.style.display='none';}}catch(e){}
  $$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===id));$('main').scrollTop=0;
  /* adia o render pesado 1 quadro para o menu/aba trocar na hora (não trava o toque) */
  if(window.requestAnimationFrame){requestAnimationFrame(function(){requestAnimationFrame(function(){render(id);});});}else{setTimeout(function(){render(id);},0);}
}
