function injectReqImport(){const v=document.getElementById('v-pick');if(!v)return;ensureSepCSS();const head=v.querySelector('.ph-head');if(!head||document.getElementById('reqImpCard'))return;
 const card=document.createElement('div');card.className='panel';card.id='reqImpCard';card.style.marginBottom='16px';
 card.innerHTML='<div class="ph"><span class="pdot"></span>Importar requisição (PDF)</div><div class="sep-drop"><div class="ic">'+((typeof ICONS!=="undefined"&&ICONS.down)?ICONS.down:'\u2b07')+'</div><div class="tx"><b>Jogue o PDF da requisição (FR.PPCF…)</b><p>Ela fica <b>aberta</b> aqui: toque <b>Atender</b> no item, vá à vaga, bipe <b>endereço + etiqueta</b> e confirme a saída — o item fica verde e soma a quantidade entregue.</p></div><button class="btn brand" id="reqImpBtn" style="flex:none">Selecionar</button></div><input type="file" id="reqImpFile" accept="application/pdf,.pdf" hidden><div id="reqCard"></div>';
 head.after(card);
 document.getElementById('reqImpBtn').onclick=()=>document.getElementById('reqImpFile').click();
 document.getElementById('reqImpFile').onchange=e=>{if(e.target.files[0]){handleReqFile(e.target.files[0]);e.target.value='';}};
 renderReqList();}
(function(){if(typeof renderPick==='function'){const _rp=renderPick;renderPick=function(){_rp();injectReqImport();};}})();

/* ===== ETIQUETAS DE BOBINA: importação (xlsx/csv) + bipagem por código T ===== */
let BOB={},LOC={};
try{BOB=JSON.parse(localStorage.getItem('wmsx_bob'))||{};}catch(e){BOB={};}
try{LOC=JSON.parse(localStorage.getItem('wmsx_loc'))||{};}catch(e){LOC={};}
var _bobVer=0;

/* ===== CATÁLOGO DE BOBINAS EM INDEXEDDB =====
   O localStorage tem teto de ~5 MB. Com 40 mil etiquetas o JSON passa disso e o
   setItem('wmsx_bob') estourava QuotaExceeded no meio do import ("Deu erro ao importar").
   Agora o catálogo mora no IndexedDB (centenas de MB) e o localStorage vira só cache
   de emergência para catálogos pequenos. */
window._bobReady=false;
var _bobIDB=(function(){
 var dbp=null;
 function open(){
  if(dbp)return dbp;
  dbp=new Promise(function(res,rej){
   try{
    var rq=indexedDB.open('wmsx',1);
    rq.onupgradeneeded=function(){try{var db=rq.result;if(!db.objectStoreNames.contains('kv'))db.createObjectStore('kv');}catch(e){}};
    rq.onsuccess=function(){res(rq.result);};
    rq.onerror=function(){rej(rq.error);};
   }catch(e){rej(e);}
  });
  return dbp;
 }
 return {
  get:function(k){return open().then(function(db){return new Promise(function(res,rej){try{var t=db.transaction('kv','readonly'),r=t.objectStore('kv').get(k);r.onsuccess=function(){res(r.result);};r.onerror=function(){rej(r.error);};}catch(e){rej(e);}});});},
  set:function(k,v){return open().then(function(db){return new Promise(function(res,rej){try{var t=db.transaction('kv','readwrite');t.objectStore('kv').put(v,k);t.oncomplete=function(){res(true);};t.onerror=function(){rej(t.error);};}catch(e){rej(e);}});});}
 };
})();

var _bobSaveT=null,_bobLSFull=false;
/* último retrato antes de cada operação destrutiva. Fica no IndexedDB e não
   participa da sincronização, evitando que uma falha remota apague a contingência. */
function criticalBackup(tipo,dados){
 try{var pacote={tipo:tipo,at:new Date().toISOString(),by:(session&&session.u)||'sistema',dados:dados};_bobIDB.set('backup-'+tipo,pacote).catch(function(e){window._DIAG=window._DIAG||{};window._DIAG.backup='falhou: '+String(e&&e.message||e);});return true;}catch(e){return false;}
}
function saveBOB(){
 _bobVer++;
 /* IDB é o dono do dado — gravação debounced (import de 40k não grava 40k vezes) */
 clearTimeout(_bobSaveT);
 _bobSaveT=setTimeout(function(){
  try{_bobIDB.set('bob',BOB).catch(function(e){console.warn('idb bob',e);});}catch(e){console.warn('idb bob',e);}
 },250);
 /* localStorage NÃO guarda mais o catálogo (é ele que enchia os 5 MB e derrubava o sync) */
 if(_bobLSFull)return;
 try{localStorage.setItem('wmsx_bob',JSON.stringify(BOB));}
  catch(e){_bobLSFull=true;try{window._DIAG=window._DIAG||{};window._DIAG.bobSave='falha local: '+String(e&&e.message||e);}catch(_){}}
}
/* carga inicial do IDB (assíncrona) — usa o que estiver maior entre IDB e o cache local */
(function(){
 try{
  _bobIDB.get('bob').then(function(v){
   if(v&&typeof v==='object'&&Object.keys(v).length>=Object.keys(BOB).length)BOB=v;
   else if(Object.keys(BOB).length){try{_bobIDB.set('bob',BOB);}catch(e){}} /* migra o que veio do localStorage */
   /* LIBERA OS ~5 MB: o catálogo passa a viver só no IndexedDB. Enquanto essa chave existia,
      o localStorage ficava cheio e TODO setItem (inclusive o saveStage do pullLight) estourava. */
    /* mantém a cópia local existente como contingência; o IndexedDB é a fonte principal */
    _bobLSFull=true;
   window._bobReady=true;
   try{if(typeof renderBobCatalog==='function'&&document.getElementById('bobTable'))renderBobCatalog();}catch(e){}
  }).catch(function(){window._bobReady=true;});
 }catch(e){window._bobReady=true;}
})();
/* busca UMA etiqueta na nuvem quando o aparelho não tem o catálogo local (busca sob demanda) */
async function bobFetch(et){
  try{
    if(!supa||!et)return null;et=String(et).trim().toUpperCase();
    var r=await Promise.race([supa.from('bobinas').select('*').eq('etiqueta',et).limit(1),new Promise(function(res){setTimeout(function(){res({data:null});},9000);})]);
    if(r&&r.data&&r.data.length){var row=r.data[0];var o={pr:row.pr,desc:row.descricao||'',pl:Number(row.pl)||0};BOB[et]=o;return o;}
    /* não achou no catálogo: procura nas ETIQUETAS rastreáveis (NF/romaneio) */
    var r2=await Promise.race([supa.from('etiquetas').select('*').eq('id',et).limit(1),new Promise(function(res){setTimeout(function(){res({data:null});},9000);})]);
    if(r2&&r2.data&&r2.data.length){var e=r2.data[0];var pr2=(e.c_prod||e.bobina||e.n_romaneio||'');var desc2=(e.gramatura||'');var pl2=Number(e.kg)||0;if(pr2){var o2={pr:String(pr2),desc:String(desc2),pl:pl2};BOB[et]=o2;return o2;}}
  }catch(e){}
  return null;
}
window.bobFetch=bobFetch;
/* Registra uma etiqueta RASTREÁVEL (gerada na Nota Fiscal/Romaneio/Vaga) dentro do catálogo BOB,
   pra ela funcionar em TUDO (receber, armazenar, mover, separar, chão) igual a bobina normal.
   Não sobrescreve um cadastro melhor já existente. */
function regBobFromEtq(id,e){try{
  id=String(id||'').trim().toUpperCase();if(!id||!e)return;
  var pr=String(e.cProd||e.bobina||e.nRomaneio||id).trim();
  var desc=String(e.xProd||e.gramatura||(e.nNF?('NF '+e.nNF):'')||'').trim();
  var pl=Number(e.kg)||0;
  var cur=BOB[id];
  if(cur&&cur.pr&&(cur.pl>0||!pl)) return; /* já tem cadastro bom: não piora */
  BOB[id]={pr:pr,desc:desc,pl:pl};saveBOB();
  try{if(typeof supa!=='undefined'&&supa&&typeof chunkUp==='function')chunkUp('bobinas',[{etiqueta:id,pr:pr,descricao:desc,pl:pl}]);}catch(_){}
}catch(err){}}
function saveLOC(){try{localStorage.setItem('wmsx_loc',JSON.stringify(LOC));}catch(e){}}
function brNum(v){if(typeof v==='number')return v;if(v==null)return 0;let s=String(v).trim().replace(/[^\d.,-]/g,'');if(!s)return 0;const lc=s.lastIndexOf(','),ld=s.lastIndexOf('.');if(lc>-1&&ld>-1){if(lc>ld)s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'');}else if(lc>-1){s=s.replace(/,/g,'.');}return parseFloat(s)||0;}

parseBobina=function(v){if(typeof window.cleanScanCode==='function')v=window.cleanScanCode(v);v=norm(v);if(BOB[v]){const rem=(BOB[v].rem!=null?BOB[v].rem:BOB[v].pl);return{et:v,pr:BOB[v].pr,desc:BOB[v].desc||'',peso:rem,pl:BOB[v].pl,rem:rem};}
  /* etiqueta rastreável (QR guarda o ID): resolve pelo cadastro da NF/romaneio → puxa o PRODUTO real, nunca o id */
  if(typeof window.etqLookup==='function'){var _le=window.etqLookup(v);if(_le){return{et:v,pr:_le.pr||'',desc:_le.desc||'',peso:_le.pl,pl:_le.pl,rem:_le.pl};}}
  const i=v.indexOf('$');if(i>0){const pr=v.slice(0,i),pe=parseFloat(v.slice(i+1).replace(',','.'));if(pr&&!isNaN(pe))return{et:'',pr,desc:'',peso:pe,pl:pe,rem:pe};}
  /* se tem CARA de id de etiqueta mas não achamos cadastro: NÃO usa o id como produto (deixa vazio) */
  var _ehId=/^\d+-\d+(-\d+)?-[0-9A-Z]{5,}$/.test(v)||/^R[0-9A-Z]{8,}$/.test(v);
  return{et:_ehId?v:'',pr:_ehId?'':v,desc:'',peso:null,pl:null,rem:null};};
/* TRAVA CENTRAL: garante que o "produto" de uma vaga nunca seja um ID de etiqueta.
   Se o valor tem cara de id, tenta resolver pro produto real (cadastro da etiqueta); se não achar, devolve vazio. */
function _ehEtqId(v){v=String(v||'');return /^\d+-\d+(-\d+)?-[0-9A-Z]{5,}$/.test(v)||/^R[0-9A-Z]{8,}$/.test(v);}
function cleanProd(v){try{
  v=(typeof norm==='function')?norm(v||''):String(v||'').trim().toUpperCase();
  if(!v)return '';
  var pareceId=_ehEtqId(v)||(typeof window.etqLookup==='function'&&!!window.etqLookup(v));
  if(!pareceId)return v; /* produto normal → mantém */
  if(typeof window.etqLookup==='function'){var e=window.etqLookup(v);if(e&&e.pr&&!_ehEtqId(e.pr))return (typeof norm==='function')?norm(e.pr):String(e.pr);}
  return ''; /* é id e não deu pra resolver → NÃO grava o id */
}catch(err){return String(v||'');}}

$('#mBob').addEventListener('input',function(){const v=$('#mBob').value;if(!v.trim())return;const b=parseBobina(v);
 if(b.et&&b.peso!=null)$('#mQty').value=b.peso;
 const pv=$('#mBobPv');if(pv&&b.et){pv.style.display='block';pv.innerHTML='<div style="display:flex;align-items:center;gap:10px;background:var(--card-2);border:1px solid var(--line);border-radius:10px;padding:9px 12px"><div style="min-width:0"><div style="font-size:.58rem;color:var(--muted);text-transform:uppercase;letter-spacing:.6px;font-weight:700">'+b.et+' · '+b.pr+'</div><div style="font-size:.8rem;margin-top:2px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(b.desc||'')+'</div></div><div style="margin-left:auto;font-family:var(--disp);font-weight:800;font-size:1.2rem">'+fmt(b.peso||0)+'<span style="font-size:.7rem;color:var(--muted)"> kg</span></div></div>';}
 else if(pv&&!b.et&&v.trim().length>1){pv.style.display='block';pv.innerHTML='<div style="font-size:.8rem;color:var(--b);font-weight:600">Etiqueta não encontrada no catálogo — importe o arquivo ou informe o peso manualmente.</div>';}
});

confirmMov=function(){if(!isAdmin()){toast('Somente admin pode movimentar',false);return;}
 const b=parseBobina($('#mBob').value),prod=(typeof cleanProd==='function')?cleanProd(b.pr):b.pr,et=b.et;let qty=Number($('#mQty').value);let c=norm($('#mLoc').value);
 if(mode==='saida'){if(!c){toast('Bipe o endereço para confirmar',false);$('#mLoc').click();return;}if(et&&LOC[et]&&c!==LOC[et]){toast('Endereço errado — a bobina '+et+' está em '+LOC[et],false);return;}}
 if(!c){toast('Bipe o endereço',false);$('#mLoc').focus();return;}
 const sp=findSpace(c);if(!sp){toast('Endereço não existe',false);return;}
 if(!prod){toast('Bipe a etiqueta',false);$('#mBob').focus();return;}
 if(!qty||qty<=0){toast('Peso inválido',false);$('#mQty').focus();return;}
 let before=Number(sp.q)||0;
 if(mode==='entrada'){
   if(et&&LOC[et]){
     if(LOC[et]===c){toast('Bobina '+et+' já está armazenada em '+c,false);return;}
     var _noStg=(typeof STAGE!=='undefined')&&STAGE.some(function(s){return s.et===et;});
     if(!_noStg){toast('Bobina '+et+' já está em '+LOC[et]+'. Faça a SAÍDA dela antes de armazenar em outro lugar.',false);return;}
     const _old=freeStored(et);if(_old){toast('Bobina '+et+' retornou de '+_old+' — armazenando de novo');before=Number(sp.q)||0;}
   }
   /* orientação de fluxo: etiqueta rastreável entrando direto pela movimentação, sem passar pelo Recebimento */
   try{if(et&&!LOC[et]&&(typeof STAGE==='undefined'||!STAGE.some(function(s){return s.et===et;}))&&typeof window.etqLookup==='function'&&window.etqLookup(et)){toast('Dica: essa etiqueta não passou pelo Recebimento. O fluxo ideal é bipar lá primeiro (NF → Recebimento → Armazenar).');}}catch(e){}
   /* UMA ETIQUETA, UM LUGAR: entrando na prateleira, sai dos chãos */
   try{if(et&&typeof window.f70HasEt==='function'&&window.f70HasEt(et)&&typeof window.f70Saida==='function'){window.f70Saida(et);toast('Saiu do Chão 70 · '+et);}}catch(e){}
   try{if(et&&typeof window.floorHasEt==='function'&&window.floorHasEt(et)&&typeof window.floorSaida==='function'){window.floorSaida(et);toast('Saiu do Chão expedição · '+et);}}catch(e){}
   if(sp.o&&sp.pr&&sp.pr!==prod&&before>0){toast('Posição ocupada por '+sp.pr,false);return;}if(before<=0){sp.pr=prod;sp.q=Number(qty)||0;}else{sp.pr=prod;sp.q=before+(Number(qty)||0);}sp.o=true;if(et){LOC[et]=c;saveLOC();if(BOB[et]){BOB[et].rem=qty;saveBOB();}}}
 else{if(sp.pr&&sp.pr!==prod){toast('Aqui tem '+sp.pr,false);return;}if(qty>before){toast('Saldo insuficiente na posição: '+fmt(before)+' kg',false);return;}sp.q=before-qty;
  if(et&&BOB[et]){const rb=(BOB[et].rem!=null?BOB[et].rem:BOB[et].pl);const ra=Math.max(0,rb-qty);BOB[et].rem=ra;saveBOB();if(ra<=0&&LOC[et]){delete LOC[et];saveLOC();}}
  else if(et&&LOC[et]&&sp.q<=0){delete LOC[et];saveLOC();}
  if(sp.q<=0){sp.q=0;sp.o=false;sp.pr='';}}
 var _un=unitOf(prod);sp.u=_un;sp.upd=nowISO();sp.by=session.u;MV.unshift({id:uid(),action:mode,w:cfg.warehouse,code:c,pr:prod,q:qty,u:_un,et:et||'',before,after:sp.o?sp.q:0,at:nowISO(),by:session.u}); /* log local enxuto: o histórico completo fica na nuvem */
 persist();/* empurra a vaga e o movimento pra nuvem NA HORA — esta é a versão ATIVA do confirmMov; sem isso o sync revertia a entrada/saída */try{if(typeof syncSpace==='function')syncSpace(sp);}catch(e){}try{if(typeof syncMov==='function')syncMov(MV[0]);}catch(e){}logAct(mode,(et?et+' · ':'')+prod+' '+(mode==='entrada'?'+':'−')+qty+' @ '+c);try{enqueue3dTask(c,mode==='entrada'?'in':'out');}catch(e){}const bobMsg=(mode==='saida'&&et&&BOB[et])?(' · bobina '+fmt(BOB[et].rem)+' '+_un.toLowerCase()):'';toast((mode==='entrada'?'Entrada':'Saída')+(et?' · '+et:'')+' · '+c+' · pos '+fmt(sp.q)+bobMsg);clearScan();renderMovRecent();$('#mLoc').focus();};
$('#confirmBtn').onclick=function(){confirmMov();};

(function(){const lab=[...document.querySelectorAll('#v-mov .lab')].find(l=>l.textContent.indexOf('Etiqueta da bobina')>-1);if(lab)lab.textContent='2 · Bipe a etiqueta da bobina (T…)';const mb=$('#mBob');if(mb)mb.placeholder='ex: T40364663';})();

function loadXLSX(){return window.XLSX?Promise.resolve():new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';s.onload=res;s.onerror=()=>rej(new Error('cdn'));document.head.appendChild(s);});}
function da(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();}
function colFind(H){const names=[].slice.call(arguments,1);for(let i=0;i<H.length;i++){const h=da(H[i]);for(const n of names)if(h.includes(n))return i;}return -1;}
function colFindP(H){const names=[].slice.call(arguments,1);for(const n of names){for(let i=0;i<H.length;i++){if(da(H[i]).includes(n))return i;}}return -1;}
function colPeso(H){
 // normaliza removendo pontos/espaços extras: "Qtd. Prod." -> "qtd prod"
 const nz=s=>da(s).replace(/[._\s]+/g,' ').trim();
 // 1) prioridade: coluna de QUANTIDADE PRODUZIDA (a verde), incluindo abreviações
 const prod=['quantidade produzida','qtd produzida','quant produzida','qtd prod','quant prod','produzida'];
 for(const t of prod){for(let i=0;i<H.length;i++){if(nz(H[i]).includes(t))return i;}}
 // 2) só se não houver coluna de produzida, usa peso líquido como reserva
 return colFindP(H,'liquido','peso liq','liq');
}
function ingestRows(rows){let hi=-1;for(let i=0;i<Math.min(rows.length,15);i++){const r=(rows[i]||[]).map(x=>String(x||'').toLowerCase());if(r.some(c=>c.includes('etiqueta'))&&r.some(c=>c.includes('produto'))){hi=i;break;}}
 if(hi<0){toast('Não achei colunas Etiqueta/Produto',false);return 0;}
 const H=rows[hi],ie=colFind(H,'etiqueta'),ip=colFind(H,'produto'),idd=colFind(H,'descri'),iq=colPeso(H);
 if(ie<0||ip<0){toast('Cabeçalho incompleto',false);return 0;}
 if(iq<0)toast('Atenção: coluna Quantidade Produzida não encontrada',false);
 let n=0;var _apAt=nowISO(),_apBy=(typeof session!=='undefined'&&session?session.u:'');for(let i=hi+1;i<rows.length;i++){const r=rows[i]||[];const et=String(r[ie]||'').trim().toUpperCase();const pr=String(r[ip]||'').trim();if(!et||!pr)continue;BOB[et]={pr,desc:idd>-1?String(r[idd]||'').trim():'',pl:iq>-1?brNum(r[iq]):0,apAt:_apAt,apBy:_apBy};n++;}
 saveBOB();return n;}
let impRows=null;
function detectHeader(rows){for(let i=0;i<Math.min(rows.length,20);i++){const r=(rows[i]||[]).map(x=>da(x));if(r.some(c=>c.includes('etiqueta'))&&r.some(c=>c.includes('produto')))return i;}return 0;}
function handleImport(file){const ext=(file.name.split('.').pop()||'').toLowerCase();$('#impStatus').innerHTML='<p style="color:var(--muted);font-size:.82rem;margin:10px 0 0">Lendo '+file.name+'…</p>';
 const done=rows=>{impRows=rows;$('#impStatus').innerHTML='';renderMapping();};
 if(ext==='csv'){const r=new FileReader();r.onload=()=>{const txt=r.result;const head=txt.split(/\r?\n/)[0]||'';const delim=(head.split(';').length>head.split(',').length)?';':',';const rows=txt.split(/\r?\n/).map(l=>l.split(delim).map(c=>c.replace(/^"|"$/g,'')));done(rows);};r.readAsText(file);}
 else{loadXLSX().then(()=>{const r=new FileReader();r.onload=()=>{try{const wb=XLSX.read(new Uint8Array(r.result),{type:'array'});const sn=wb.SheetNames.find(s=>/apont/i.test(s))||wb.SheetNames[wb.SheetNames.length-1];done(XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:true,defval:''}));}catch(e){toast('Erro ao ler o arquivo',false);}};r.readAsArrayBuffer(file);}).catch(()=>toast('Sem internet p/ ler .xlsx — exporte como CSV',false));}}
function renderMapping(){const rows=impRows;if(!rows||!rows.length)return;
 const hrEl=$('#impHrow');let hi=(hrEl&&hrEl.value)?Math.max(0,parseInt(hrEl.value,10)-1):detectHeader(rows);
 const H=rows[hi]||[];
 const sel=(id,g)=>'<select class="input" id="'+id+'">'+H.map((h,i)=>'<option value="'+i+'" '+(i===g?'selected':'')+'>'+(String(h||'').trim()||('Coluna '+(i+1)))+'</option>').join('')+'</select>';
 const gE=colFind(H,'etiqueta'),gP=colFind(H,'produto'),gD=colFind(H,'descri'),gQ=colPeso(H);
 $('#impMap').innerHTML='<div class="panel" style="max-width:700px;margin-top:16px"><div class="ph"><span class="pdot"></span>Conferir colunas antes de importar</div>'+
  '<label class="fld"><span class="lab">Linha do cabeçalho</span><input class="input" id="impHrow" type="number" min="1" value="'+(hi+1)+'" style="max-width:130px"></label>'+
  '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:6px">'+
   '<label class="fld"><span class="lab">Etiqueta</span>'+sel('mapEt',gE)+'</label>'+
   '<label class="fld"><span class="lab">Produto (0303…)</span>'+sel('mapPr',gP)+'</label>'+
   '<label class="fld"><span class="lab">Descrição</span>'+sel('mapDe',gD)+'</label>'+
   '<label class="fld"><span class="lab">Peso (Qtd. Produzida)</span>'+sel('mapPl',gQ)+'</label>'+
  '</div>'+
  '<div class="lab" style="margin-bottom:6px">Pré-visualização</div><div id="mapPrev" style="font-family:var(--mono);font-size:.76rem;color:var(--muted);background:var(--card-2);border:1px solid var(--line);border-radius:10px;padding:11px 13px;margin-bottom:14px;line-height:1.7"></div>'+
  '<button class="btn brand" id="mapDo" style="width:100%;height:48px">Importar com estas colunas</button></div>';
 $('#impHrow').onchange=renderMapping;['mapEt','mapPr','mapDe','mapPl'].forEach(id=>$('#'+id).onchange=mapPreview);$('#mapDo').onclick=doImport;mapPreview();}
function mapPreview(){const rows=impRows,hi=Math.max(0,parseInt($('#impHrow').value,10)-1),ie=+$('#mapEt').value,ip=+$('#mapPr').value,idd=+$('#mapDe').value,iq=+$('#mapPl').value;let html='',c=0;for(let i=hi+1;i<rows.length&&c<4;i++){const r=rows[i]||[];if(!String(r[ie]||'').trim())continue;html+='<div>'+String(r[ie]||'')+' · '+String(r[ip]||'')+' · '+String(r[idd]||'').slice(0,22)+' · <b style="color:var(--in)">'+fmt(brNum(r[iq]))+' kg</b></div>';c++;}$('#mapPrev').innerHTML=html||'<div>sem linhas de exemplo</div>';}
function doImport(){var _delta=[];try{const rows=impRows,hi=Math.max(0,parseInt($('#impHrow').value,10)-1),ie=+$('#mapEt').value,ip=+$('#mapPr').value,idd=+$('#mapDe').value,iq=+$('#mapPl').value;let n=0,comPeso=0,jaExistiam=0;var _apAt=nowISO(),_apBy=(typeof session!=='undefined'&&session?session.u:'');for(let i=hi+1;i<rows.length;i++){const r=rows[i]||[];const et=String(r[ie]||'').trim().toUpperCase();const pr=String(r[ip]||'').trim();if(!et||!pr)continue;const pl=brNum(r[iq]);const de=String(r[idd]||'').trim();if(pl>0)comPeso++;const _prev=BOB[et];const _novoOuMudou=(!_prev)||(_prev.pr!==pr)||((_prev.desc||'')!==de)||((Number(_prev.pl)||0)!==pl);BOB[et]={pr,desc:de,pl,apAt:_apAt,apBy:_apBy};if(_novoOuMudou)_delta.push(et);else jaExistiam++;n++;}saveBOB();if(typeof syncBobDelta==='function')syncBobDelta(_delta);$('#impMap').innerHTML='';finishImport(n);if(jaExistiam>0)toast(_delta.length+' nova(s)/alterada(s) enviada(s) · '+jaExistiam+' já estavam salvas (mantidas)');if(n>0&&comPeso===0)toast('Importado, mas o peso veio zerado — confira a coluna Quantidade Produzida',false);}catch(err){try{if(typeof syncBobDelta==='function')syncBobDelta(_delta);}catch(_){}try{toast('Deu erro ao importar ('+((err&&err.message)||err)+'). O que entrou foi enviado — toque em "Enviar p/ nuvem".',false);}catch(_){}}}
function finishImport(n){if(n>0){toast(n+' etiquetas importadas');logAct('import',n+' etiquetas');$('#impStatus').innerHTML='<p style="color:var(--in);font-size:.82rem;margin:10px 0 0;font-weight:600">✓ '+n+' etiquetas no catálogo</p>';}renderBobCatalog();}
function bobImportUI(){return '<div class="panel" style="max-width:680px;text-align:center;border-style:dashed"><div style="color:var(--brand);font-size:2rem;display:flex;justify-content:center;margin-bottom:10px">'+ICONS.down+'</div><div style="font-weight:700;font-family:var(--disp)">Importar arquivo de etiquetas</div><p style="color:var(--muted);font-size:.82rem;margin:6px auto 16px;max-width:460px">Jogue a planilha de apontamentos (.xlsx) ou CSV. O sistema lê <b>Etiqueta</b>, <b>Produto</b> (0303…), <b>Descrição</b> e <b>Quantidade Produzida</b> (a coluna verde).</p><button class="btn brand" id="impBtn">Selecionar arquivo</button><input type="file" id="impFile" accept=".xlsx,.xls,.csv" hidden></div><div id="impStatus"></div><div id="impMap"></div><div class="toolbar" style="margin-top:18px"><div class="search"><span class="si">'+ICONS.search+'</span><input id="bobSearch" placeholder="buscar etiqueta ou produto"></div><span class="count" id="bobCount"></span></div><div class="tbl-wrap"><table class="tbl" id="bobTable"></table></div>';}
function printBobLabel(et){const o=BOB[et];if(!o){toast('Etiqueta não encontrada',false);return;}
 let host=document.getElementById('bobPrintHost');if(host)host.remove();
 host=document.createElement('div');host.id='bobPrintHost';
 host.innerHTML='<div class="bobprn"><div class="bpbar"></div><div class="bpin">'
  +'<div class="bphead"><img src="'+PACKEM_IMG+'" class="bplogo"><div class="bpbt">PACKEM<span>BOBINA</span></div></div>'
  +'<div class="bpet">'+et+'</div>'+bc39(et)
  +'<div class="bppr">'+(o.pr||'')+'</div>'
  +((o.pl>0)?'<div class="bpw">'+fmt(o.pl)+' KG</div>':'')
  +(o.desc?'<div class="bpd">'+o.desc+'</div>':'')
  +'</div></div>';
 document.body.appendChild(host);
 let st=document.getElementById('bobPrintStyle');if(!st){st=document.createElement('style');st.id='bobPrintStyle';document.head.appendChild(st);}
 st.textContent='#bobPrintHost{position:fixed;left:-9999px;top:0}'
  +'@media print{@page{size:100mm 150mm;margin:0}html,body{background:#fff!important}*{visibility:visible!important}body>*{display:none!important}body>#bobPrintHost{display:block!important}#bobPrintHost,#bobPrintHost *{visibility:visible!important}#bobPrintHost{position:absolute!important;left:0;top:0;width:100mm}'
  +'.bobprn{box-sizing:border-box;width:100mm;height:150mm;display:flex;flex-direction:column;color:#000;font-family:Arial,Helvetica,sans-serif;page-break-after:always}'
  +'.bpbar{height:6mm;background:#EA5A0C}'
  +'.bpin{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:6mm;gap:3mm}'
  +'.bphead{display:flex;align-items:center;gap:3mm}.bplogo{width:14mm;height:14mm;border-radius:2mm;object-fit:cover}'
  +'.bpbt{font-weight:800;font-size:6mm;text-align:left;display:flex;flex-direction:column;line-height:1}.bpbt span{font-weight:700;font-size:3mm;color:#666;letter-spacing:1mm;margin-top:1mm}'
  +'.bpet{font-family:"Courier New",monospace;font-weight:800;font-size:11mm;letter-spacing:.5mm;margin-top:2mm}'
  +'.bobprn svg.bc{width:84mm;height:24mm}'
  +'.bppr{font-family:"Courier New",monospace;font-weight:700;font-size:7mm;word-break:break-all}'
  +'.bpw{font-weight:800;font-size:10mm}'
  +'.bpd{font-size:4mm;color:#333;max-width:86mm}}';
 setTimeout(function(){try{window.print();}catch(_pe){}setTimeout(function(){try{host.remove();st.remove();}catch(_){}},800);},80);}
function renderBobCatalog(){const sb=$('#bobSearch');const q=norm(sb?sb.value:'');let arr=Object.keys(BOB).map(et=>Object.assign({et},BOB[et]));if(q)arr=arr.filter(x=>x.et.includes(q)||(x.pr||'').toUpperCase().includes(q)||(x.desc||'').toUpperCase().includes(q));arr.sort((a,b)=>a.et<b.et?-1:1);const all=Object.keys(BOB).length,cp=Object.values(BOB).filter(o=>o.pl>0).length;const c=$('#bobCount');if(c)c.textContent=all+' etiquetas · '+cp+' com peso';const t=$('#bobTable');if(!t)return;
 t.innerHTML='<thead><tr><th>Etiqueta</th><th>Produto</th><th class="num">Peso líq. (kg)</th><th>Descrição</th><th>Situação</th><th style="text-align:center">Imprimir</th></tr></thead><tbody>'+(arr.length?arr.slice(0,500).map(x=>'<tr><td class="mono">'+x.et+'</td><td class="mono">'+x.pr+'</td><td class="num"><b style="color:var(--ink)">'+fmt(x.pl||0)+'</b></td><td style="color:var(--muted);max-width:280px;overflow:hidden;text-overflow:ellipsis">'+(x.desc||'—')+'</td><td>'+(LOC[x.et]?'<span class="pill in">em '+LOC[x.et]+'</span>':'<span class="pill muted">disponível</span>')+'</td><td style="text-align:center"><button class="gbtn" style="padding:5px 11px;font-size:.72rem" onclick="printBobLabel(\''+x.et+'\')">'+(typeof ICONS!=='undefined'&&ICONS.print?ICONS.print:'')+' imprimir</button></td></tr>').join(''):'<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--muted)">Nenhuma etiqueta importada ainda. Clique em “Selecionar arquivo”.</td></tr>')+'</tbody>';}
function addManualBob(){const et=String(($('#mbEt').value||'')).trim().toUpperCase();const pr=String(($('#mbPr').value||'')).trim();const desc=String(($('#mbDe').value||'')).trim();const pl=brNum($('#mbPl').value);if(!et){toast('Informe a etiqueta',false);$('#mbEt').focus();return;}if(!pr){toast('Informe o produto',false);$('#mbPr').focus();return;}const existed=!!BOB[et];BOB[et]={pr,desc,pl};saveBOB();if(typeof syncBobAll==='function')syncBobAll();logAct('import',(existed?'editou':'cadastrou')+' etiqueta '+et);['mbEt','mbPr','mbDe','mbPl'].forEach(id=>{const e=$('#'+id);if(e)e.value='';});$('#mbEt').focus();renderBobCatalog();toast(existed?'Etiqueta '+et+' atualizada':'Etiqueta '+et+' cadastrada');}
function wireManualBob(){const b=$('#mbAdd');if(b)b.onclick=addManualBob;['mbEt','mbPr','mbDe','mbPl'].forEach(id=>{const e=$('#'+id);if(e)e.addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();addManualBob();}});});}
