ICONS.inbox='<svg class="i" viewBox="0 0 24 24"><path d="M3 13l3-8h12l3 8v6a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M3 13h5l1 3h6l1-3h5"/></svg>';
let STAGE=[];try{STAGE=JSON.parse(localStorage.getItem('wmsx_stage'))||[];}catch(e){STAGE=[];}
function saveStage(){try{localStorage.setItem('wmsx_stage',JSON.stringify(STAGE));}catch(e){}}
function updateStageBadge(){const n=document.querySelector('.nav[data-view="v-recv"]');if(!n)return;let b=n.querySelector('.badge');if(!STAGE.length){if(b)b.remove();return;}if(!b){b=document.createElement('span');b.className='badge';b.style.cssText='margin-left:auto;background:var(--brand);color:#fff;font-size:.66rem;font-weight:700;padding:1px 8px;border-radius:999px;font-family:var(--mono)';n.appendChild(b);}b.textContent=STAGE.length;}
function freeStored(et){
 if(!et||typeof LOC==='undefined'||!LOC[et])return null;
 const c=LOC[et],sp=findSpace(c);
 const rem=(typeof BOB!=='undefined'&&BOB[et]&&BOB[et].rem!=null)?BOB[et].rem:((typeof BOB!=='undefined'&&BOB[et])?BOB[et].pl:(sp?sp.q:0));
 if(sp){const before=sp.q||0;const out=Math.min(before,rem||before);sp.q=Math.max(0,before-out);if(sp.q<=0){sp.q=0;sp.o=false;sp.pr='';}sp.upd=nowISO();sp.by=session.u;
  MV.unshift({id:uid(),action:'saida',w:cfg.warehouse,code:c,pr:(typeof BOB!=='undefined'&&BOB[et]?BOB[et].pr:sp.pr),q:out,u:'KG',et:et,before,after:sp.o?sp.q:0,at:nowISO(),by:session.u,note:'retorno de produção'}); /* log local enxuto: o histórico completo fica na nuvem */
  if(typeof syncSpace==='function')syncSpace(sp);if(typeof syncMov==='function'&&MV[0])syncMov(MV[0]);}
 delete LOC[et];saveLOC();if(typeof BOB!=='undefined'&&BOB[et]){BOB[et].rem=0;saveBOB();}
 if(typeof syncDelLoc==='function')syncDelLoc(et);persist();try{enqueue3dTask(c,'out');}catch(e){}
 return c;
}
function placeBobina(et,pr,pl,c){c=norm(c);if(typeof cleanProd==='function')pr=cleanProd(pr);const sp=findSpace(c);if(!sp){toast('Endereço '+c+' não existe',false);return false;}
 if(et&&typeof LOC!=='undefined'&&LOC[et]){
   /* JÁ está armazenada. Só pode rearmazenar se estiver voltando pelo intermediário (STAGE).
      Senão, seria a MESMA bobina em dois lugares (saldo duplicado) — bloqueia e manda dar saída. */
   var noStage=(typeof STAGE!=='undefined')&&STAGE.some(function(s){return s.et===et;});
   if(LOC[et]===c){toast('Bobina '+et+' já está armazenada em '+c,false);return false;}
   if(!noStage){toast('Bobina '+et+' já está em '+LOC[et]+'. Faça a SAÍDA dela antes de armazenar em outro lugar.',false);return false;}
   const _old=freeStored(et);if(_old)toast('Bobina '+et+' retornou de '+_old+' — armazenando de novo');
 }
 if(sp.o&&sp.pr&&sp.pr!==pr){toast('Posição ocupada por '+sp.pr,false);return false;}const before=Number(sp.q)||0;sp.pr=pr;sp.q=before+(Number(pl)||0);sp.o=true;sp.u='KG';sp.upd=nowISO();sp.by=session.u;if(et){LOC[et]=c;saveLOC();}MV.unshift({id:uid(),action:'entrada',w:cfg.warehouse,code:c,pr,q:pl,u:'KG',et:et||'',before,after:sp.q,at:nowISO(),by:session.u}); /* log local enxuto: o histórico completo fica na nuvem */persist();if(typeof syncSpace==='function')syncSpace(sp);logAct('entrada',(et?et+' · ':'')+pr+' +'+pl+' @ '+c);try{enqueue3dTask(c,'in');}catch(e){}
 /* armazenou na prateleira → tira do chão (não pode ficar em dois lugares; a prateleira é a entrada mais recente) */
 if(et){
   try{if(typeof window.f70HasEt==='function'&&window.f70HasEt(et)&&typeof window.f70Saida==='function'){window.f70Saida(et);toast('Saiu do Chão 70 · '+et);}}catch(e){}
   try{if(typeof window.floorHasEt==='function'&&window.floorHasEt(et)&&typeof window.floorSaida==='function'){window.floorSaida(et);toast('Saiu do Chão expedição · '+et);}}catch(e){}
 }
 return true;}
async function recvAdd(v){if(!isAdmin()){toast('Somente admin pode receber',false);return;}if(typeof window.cleanScanCode==='function')v=window.cleanScanCode(v);const et=norm(v);if(!et)return;var b=BOB[et];if(!b&&typeof window.etqLookup==='function'){b=window.etqLookup(et);}if(!b){b=await bobFetch(et);}if(!b){toast('Etiqueta '+et+' não está no catálogo — importe o arquivo ou gere pela Nota Fiscal',false);return;}if(LOC[et]){const old=freeStored(et);toast('Bobina '+et+' retornou de '+old+' — liberada p/ recebimento');}
  /* Chão de EXPEDIÇÃO é outro lugar físico: se a bobina voltou pro recebimento, sai de lá.
     Chão 70 NÃO — ver o bloco logo abaixo, onde ela ENTRA no Chão 70. */
  try{if(typeof window.floorHasEt==='function'&&window.floorHasEt(et)&&typeof window.floorSaida==='function'){window.floorSaida(et);toast('Saiu do Chão expedição · '+et);}}catch(e){}
  if(STAGE.some(s=>s.et===et)){toast('Etiqueta já no intermediário',false);return;}
  var _it={et,pr:b.pr,desc:b.desc,pl:b.pl,at:nowISO(),by:session.u};
  STAGE.unshift(_it);saveStage();
  /* ===== RECEBEU = ESTÁ NO CHÃO 70 =====
     Antes, receber TIRAVA a bobina do Chão 70 pela regra "uma etiqueta, um lugar". Só que
     intermediário e Chão 70 não são dois lugares concorrentes: intermediário é um ESTADO
     (recebida, ainda sem endereço) e Chão 70 é o LUGAR FÍSICO onde ela fica parada enquanto
     isso. Quem for contar o Chão 70 precisa enxergar essa bobina — ela está lá, no chão.
     Ela só sai do Chão 70 quando sai do chão de verdade: guardada na prateleira
     (placeBobina) ou mandada pra produção (commitProducao). */
  try{if(typeof window.f70Entrada==='function')window.f70Entrada(_it,true);}catch(e){}
  /* TRAVA ANTI-CORRIDA: sem isso o pullLight (que roda a cada 2,5s) sobrescrevia STAGE com a
     versão da nuvem ANTES do syncStage chegar lá — e o bipe sumia do estoque intermediário. */
  try{markLocalWrite();}catch(e){}
  try{if(typeof syncStage==='function')syncStage(_it);}catch(e){}
  MV.unshift({id:uid(),action:'recebimento',w:cfg.warehouse,code:'INTERMEDIÁRIO',pr:b.pr||'',q:Number(b.pl)||0,u:(typeof unitOf==='function'?unitOf(b.pr):'KG'),et:et,before:0,after:Number(b.pl)||0,at:nowISO(),by:session.u}); /* log local enxuto: o histórico completo fica na nuvem */try{if(typeof syncMov==='function')syncMov(MV[0]);}catch(e){}logAct('recebimento',et+' · '+b.pr);renderRecv();updateStageBadge();toast('Recebido: '+et+' · '+fmt(b.pl)+' '+(typeof unitOf==='function'?unitOf(b.pr).toLowerCase():'kg'));stationPrint({et:et,pr:b.pr,desc:b.desc,pl:b.pl});}
