   +'.zlbl .zcode{font-family:Arial,"Segoe UI",Helvetica,sans-serif;font-weight:800;line-height:1;letter-spacing:-0.4mm;color:#0a0c10}'
   +'.zlbl .zmeta{display:flex;color:#444;font-weight:700;letter-spacing:.2mm}.zlbl .zmeta b{color:#0a0c10}'
   +'.zlbl .zqr{display:flex;align-items:center;justify-content:center;width:100%}.zlbl .zqr svg{width:100%;height:auto;display:block;margin:0 auto}svg.qr{max-width:100%;height:auto}svg.bc{width:100%;height:auto}'
   +'.zlbl .zfoot{color:#777;font-weight:700;letter-spacing:.3mm}';
