function markPrinted(et){try{var a=JSON.parse(localStorage.getItem('wmsx_printedEts')||'[]');if(a.indexOf(et)<0){a.push(et);if(a.length>800)a=a.slice(-800);localStorage.setItem('wmsx_printedEts',JSON.stringify(a));}}catch(e){}}
