    let all=[];try{all=JSON.parse(localStorage.getItem(AUDIT_KEY)||'[]');if(!Array.isArray(all))all=[];}catch(e){}all.push(ev);if(all.length>3000)all=all.slice(-3000);localStorage.setItem(AUDIT_KEY,JSON.stringify(all));
