  b.style.cssText='position:fixed;bottom:10px;right:12px;z-index:9998;display:flex;align-items:center;gap:5px;font:700 10px Inter,system-ui,sans-serif;color:var(--faint);background:var(--card);border:1px solid var(--line);border-radius:99px;padding:5px 11px;cursor:pointer;opacity:.45;transition:opacity .2s ease';
  b.onmouseenter=function(){b.style.opacity='1';};
