 function safeArr(v){return Array.isArray(v)?v:[]}
 function safeObj(v){return v&&typeof v==='object'?v:{}}
 function vrWhen(v){if(!v)return 'sem data';var z=new Date(v);return isNaN(z.getTime())?String(v):z.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
 function vrData(){var et=Object.keys(safeObj(typeof ETQ==='undefined'?{}:ETQ)).map(function(k){return ETQ[k]||{}}),st=safeArr(typeof STAGE==='undefined'?[]:STAGE),slots=safeArr(typeof S==='undefined'?[]:S),moves=safeArr(typeof MV==='undefined'?[]:MV),wh=(typeof cfg!=='undefined'&&cfg)?cfg.warehouse:null,occ=slots.filter(function(x){return x&&x.o&&(!wh||x.w===wh)}),today=new Date().toDateString(),out=moves.filter(function(x){return x&&x.action==='saida'&&new Date(x.at).toDateString()===today}),old=st.filter(function(x){return x&&x.at&&Date.now()-Date.parse(x.at)>14400000}).length;return{et:et,ger:et.filter(function(x){return x.status==='gerada'}).length,rec:et.filter(function(x){return x.status==='entrada'}).length,st:st,occ:occ,out:out,old:old,moves:moves,docs:Object.keys(safeObj(typeof NFS==='undefined'?{}:NFS)).length+Object.keys(safeObj(typeof ROMS==='undefined'?{}:ROMS)).length,kg:st.reduce(function(a,x){return a+(Number(x.pl)||0)},0),slots:slots.length}}
