  if(/(temos|tem |há |ha |existe|saldo).*(bobina|material|produto|pet|tecido|filme|cadar[cç]o|al[cç]a)|(bobina|material|produto|pet|tecido|filme|cadar[cç]o|al[cç]a).*(estoque|temos|existe)/.test(low))return saldoMaterialDescricao(t);
  if(/estoque|resumo|saldo/.test(low)&&!num){var prods={},kg=0,mt=0;occ.forEach(function(x){if(x.pr)prods[x.pr]=1;var u=(typeof unitOf==='function'?unitOf(x.pr):'KG'),v=Number(x.q)||0;if(u==='MT')mt+=v;else kg+=v;});return 'Resumo atual do estoque:\n• '+occ.length+' posições ocupadas\n• '+Object.keys(prods).length+' produtos distintos\n• '+(typeof fmt==='function'?fmt(kg):kg.toLocaleString('pt-BR'))+' kg\n• '+(typeof fmt==='function'?fmt(mt):mt.toLocaleString('pt-BR'))+' metros';}
  if(/romaneio/.test(low)){var achRom=[];try{Object.keys(ROMS||{}).forEach(function(k){var d=ROMS[k]||{},id=String(d.nRomaneio||k);if(!num||id===num||id.indexOf(num)>=0)achRom.push({key:k,doc:d,id:id});});}catch(e){}if(num){if(!achRom.length)return 'Não encontrei o romaneio '+num+'. Confira o número informado.';ultimoRomaneioWmsAi=achRom[0];ultimoAssuntoWmsAi='romaneio';return relatorioRomaneio(achRom[0].doc,achRom[0].key);}if(/hoje|data de hoje/.test(low))return romaneiosHoje();if(/geral|todos|resumo completo|resumo dos/.test(low))return resumoRomaneios();return 'Você quer consultar um romaneio específico, os romaneios de hoje ou o resumo geral? Informe o número ou escreva “romaneios hoje” ou “romaneios em geral”.';}
  if(/nf|nota fiscal/.test(low)&&dataConsulta(t))return nfPorData(t);
  if(/(nf|nota fiscal).*(hoje|data de hoje)|(hoje|data de hoje).*(nf|nota fiscal)|(hoje|data de hoje).*(entrou|entraram|quantas)/.test(low))return nfEntradasHoje();
  if(/(quantas|quanto|resumo|total|teve|foram).*(entrada|entrou|entraram|recebimento).*(hoje)|(entrada|entrou|entraram|recebimento).*(hoje)|(quantas|quanto).*(entrou|entraram)/.test(low))return ultimoMaterialWmsAi?entradasHojeDoMaterial(ultimoMaterialWmsAi):resumoMovimentos('entrada');
  if(/(quantas|resumo|total|teve|foram).*(sa[ií]da).*(hoje)|sa[ií]da.*hoje/.test(low))return resumoMovimentos('saida');
