 function exportaCsv(){if(!ultimaRespostaWmsAi){fala('Ainda não há uma resposta para exportar.','bot');return;}var conteudo='"Assistente WMS"\r\n"'+ultimaRespostaWmsAi.replace(/"/g,'""').replace(/\n/g,'"\r\n"')+'"';if(typeof dl==='function')dl('resposta_assistente_wms.csv',conteudo,'text/csv;charset=utf-8');}
