 box.querySelector('.wmsAiClose').onclick=function(){box.classList.remove('open');};box.querySelector('.wmsAiForm').onsubmit=function(e){e.preventDefault();envia(inp.value);};box.querySelectorAll('.wmsAiSug button').forEach(function(b){b.onclick=function(){var ex=b.getAttribute('data-ai-export');if(ex==='csv'){exportaCsv();return;}if(ex==='pdf'){imprimeResposta();return;}var q=b.textContent;if(q==='Localizar produto')q='Onde está o produto ';else if(q==='Consultar NF')q='Consultar NF ';else if(q==='NFs hoje')q='Quantas NFs entraram hoje?';else if(q==='Romaneios hoje')q='Quantos romaneios entraram hoje?';else if(q==='Vagas livres')q='Quantas vagas estão livres?';if(/produto |NF $/.test(q)){inp.value=q;inp.focus();}else envia(q);};});
